                FfiConverterTypeTorBlock.write(value.`reason`, buf)
                Unit
            }
            is TorState.Failed -> {
                buf.putInt(5)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
